package main

import("fmt";"net/http")

const css="*{box-sizing:border-box}body{margin:0;background:#09090b;color:#f4f4f5;font:15px system-ui,sans-serif}.shell{min-height:100vh;display:flex}.side{width:235px;padding:22px;border-right:1px solid #27272a;background:#101014}.brand{font-size:21px;font-weight:800;margin-bottom:35px}.nav{display:grid;gap:7px}.nav div{padding:11px 13px;border-radius:10px;color:#a1a1aa}.nav .on{background:#27272a;color:#fff}.main{flex:1;max-width:1200px;width:100%;padding:28px;margin:auto}.top{display:flex;justify-content:space-between;align-items:center}.muted{color:#a1a1aa}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:22px}.card{background:#141417;border:1px solid #27272a;border-radius:17px;padding:20px}.value{font-size:28px;font-weight:750;margin-top:7px}.table{margin-top:20px}.row{display:flex;justify-content:space-between;gap:12px;padding:15px 0;border-bottom:1px solid #27272a}.logout{background:#fff;color:#111;border:0;border-radius:10px;padding:9px 13px}@media(max-width:720px){.shell{display:block}.side{width:auto;border-right:0;border-bottom:1px solid #27272a;padding:15px 17px}.brand{margin:0 0 12px}.nav{display:flex;overflow:auto}.nav div{white-space:nowrap}.main{padding:19px 15px}.grid{grid-template-columns:1fr}.row{display:block}.row span{display:block;margin-top:5px}}"

func dashboard(w http.ResponseWriter){
 w.Header().Set("Content-Type","text/html; charset=utf-8")
 html:="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><style>"+css+"</style></head><body><div class='shell'><aside class='side'><div class='brand'>◈ Axy Router</div><nav class='nav'><div class='on'>Overview</div><div>Providers</div><div>Models</div><div>API Keys</div><div>Logs</div><div>Settings</div></nav></aside><main class='main'><div class='top'><div><h1 style='margin:0'>Overview</h1><p class='muted'>AI gateway control center · v1</p></div><form method='post' action='/logout'><button class='logout'>Logout</button></form></div><div class='grid'><div class='card'><span class='muted'>Gateway</span><div class='value'>Online</div></div><div class='card'><span class='muted'>Providers</span><div class='value' id='providers'>—</div></div><div class='card'><span class='muted'>API</span><div class='value'>Ready</div></div></div><section class='card table'><h2>Provider status</h2><div id='list' class='muted'>Loading...</div></section></main></div><script>fetch('/api/providers').then(r=>r.json()).then(x=>{document.querySelector('#providers').textContent=x.providers.length;document.querySelector('#list').innerHTML=x.providers.length?x.providers.map(p=>'<div class=&quot;row&quot;><b>'+p.name+'</b><span>'+p.model+' · '+(p.enabled?'Enabled':'Disabled')+'</span></div>').join(''):'No providers configured yet.'})</script></body></html>"
 fmt.Fprint(w,html)
}

func loginPage(msg string){
 w.Header().Set("Content-Type","text/html; charset=utf-8")
 html:="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{margin:0;background:#09090b;color:#fff;font:16px system-ui;min-height:100vh;display:grid;place-items:center}.box{width:min(360px,88vw);padding:28px;background:#141417;border:1px solid #27272a;border-radius:20px}.box input,.box button{width:100%;padding:14px;border-radius:12px;margin-top:10px}.box input{background:#09090b;color:#fff;border:1px solid #3f3f46}.box button{border:0;font-weight:700}</style></head><body><form class='box' method='post'><h1>Axy Router</h1><p style='color:#a1a1aa'>Admin PIN untuk masuk</p><input name='pin' type='password' inputmode='numeric' maxlength='12' autofocus placeholder='PIN'><button>Masuk</button><p style='color:#f87171'>"+msg+"</p></form></body></html>"
 fmt.Fprint(w,html)
}
